?><!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Images du réseau local — MIARADI-TRAVEL</title>
<style>
:root{--red:#922d20;--paper:#fbf8f5;--ink:#172238;--muted:#65738a;--line:#eadfdd;--white:#fff}
*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.55 Inter,"Segoe UI",Arial,sans-serif}header{background:#fff;border-bottom:1px solid var(--line);padding:16px clamp(18px,4vw,52px);display:flex;align-items:center;justify-content:space-between;gap:18px}.brand{font-weight:850;letter-spacing:.05em;color:var(--red)}a{color:var(--red)}.back{font-size:13px;text-decoration:none;font-weight:700}main{max-width:1180px;margin:auto;padding:34px clamp(16px,4vw,44px) 60px}.kicker{font-size:11px;letter-spacing:.17em;font-weight:800;color:var(--red)}h1{font-size:clamp(27px,4vw,38px);line-height:1.15;letter-spacing:-.04em;margin:8px 0 10px}.intro{max-width:720px;color:var(--muted);margin:0 0 24px}.notice{min-height:24px;padding:12px 14px;border-radius:8px;background:#fff;border:1px solid var(--line);margin:16px 0;color:var(--muted)}.notice.error{border-color:#e9aaa3;color:#9a2d20}.notice.success{border-color:#a6d6b7;color:#22643b}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.card{background:#fff;border:1px solid var(--line);border-radius:14px;overflow:hidden;box-shadow:0 8px 24px #34221a08;min-width:0}.preview{width:100%;aspect-ratio:16/9;display:block;object-fit:cover;background:#f0e9e4;border-bottom:1px solid var(--line)}.card-body{padding:20px}.slot{font-size:10px;letter-spacing:.15em;color:var(--red);font-weight:800;text-transform:uppercase}.card h2{font-size:20px;line-height:1.2;margin:5px 0 14px}label{display:grid;gap:6px;font-size:12px;font-weight:750;margin:12px 0}input[type=text],textarea,input[type=file]{width:100%;font:inherit;font-size:14px;padding:11px 12px;border:1px solid #ddd3ce;border-radius:7px;background:#fff;color:var(--ink)}textarea{min-height:66px;resize:vertical}input[type=file]{font-size:12px;padding:9px}.hint{font-size:11px;color:var(--muted);font-weight:400}.actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:16px}button{border:0;border-radius:8px;padding:11px 16px;background:var(--red);color:#fff;font-weight:750;cursor:pointer}button:disabled{opacity:.6;cursor:wait}.state{font-size:12px;color:var(--muted)}@media(max-width:680px){header{padding:14px 16px}.grid{grid-template-columns:1fr}main{padding-top:25px}.card-body{padding:16px}}
</style></head><body>
<header><div class="brand">MIARADI <span style="font-weight:400;color:#6b7280">/ ADMIN</span></div><a class="back" href="index.php">← Retour au tableau de bord</a></header>
<main><p class="kicker">CONTENU DU SITE · PHOTOS</p><h1>Réseau local & rencontres</h1>
<p class="intro">Gérez les quatre images de la section « Derrière chaque voyage, des rencontres » affichée sur la page d’accueil. Téléversez une photo JPG, PNG ou WebP (8 Mo maximum), modifiez son texte alternatif et enregistrez. Les changements sont visibles sur le site public après actualisation.</p>
<div id="notice" class="notice" role="status" aria-live="polite">Chargement des images…</div><div id="partner-grid" class="grid"></div></main>
<script>
const csrfToken = <?= json_encode($csrf, JSON_HEX_TAG | JSON_HEX_APOS | JSON_HEX_AMP | JSON_HEX_QUOT) ?>;
const slots=[
{key:'feature',label:'Image principale',defaultTitle:'Paysages de Madagascar',defaultDescription:'Découvrir Madagascar avec celles et ceux qui le connaissent.',defaultAlt:'Paysage naturel de Madagascar'},
{key:'guide',label:'Carte 1',defaultTitle:'Guides locaux',defaultDescription:'Partager les richesses du territoire.',defaultAlt:'Guide local à Madagascar'},
{key:'lodging',label:'Carte 2',defaultTitle:'Hébergements',defaultDescription:'Des étapes choisies avec soin.',defaultAlt:'Hébergement au cœur de la nature malgache'},
{key:'crafts',label:'Carte 3',defaultTitle:'Artisans & savoir-faire',defaultDescription:'Découvrir les traditions vivantes.',defaultAlt:'Artisanat malgache traditionnel'}];
const $=(s,r=document)=>r.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function notice(message,type=''){const el=$('#notice');el.textContent=message;el.className='notice '+type;}
function render(items){const byKey=new Map(items.map(x=>[x.slot_key,x]));
$('#partner-grid').innerHTML=slots.map(slot=>{const item=byKey.get(slot.key)||{};return '<article class="card" data-slot="'+slot.key+'"><img class="preview" alt="" src="'+esc(item.image_url||'')+'" '+(!item.image_url?'hidden':'')+'><div class="card-body"><div class="slot">'+esc(slot.label)+'</div><h2>'+esc(slot.defaultTitle)+'</h2><form class="partner-form" enctype="multipart/form-data"><input type="hidden" name="slot_key" value="'+slot.key+'"><label>Titre affiché<input type="text" name="title_fr" maxlength="120" required value="'+esc(item.title_fr||slot.defaultTitle)+'"></label><label>Description affichée<textarea name="description_fr" maxlength="500">'+esc(item.description_fr||slot.defaultDescription)+'</textarea></label><label>Texte alternatif (accessibilité)<input type="text" name="alt_text" maxlength="250" required value="'+esc(item.alt_text||slot.defaultAlt)+'"></label><label>Nouvelle photo <span class="hint">JPG, PNG ou WebP · 8 Mo maximum</span><input type="file" name="image" accept="image/jpeg,image/png,image/webp"></label><div class="actions"><button type="submit">Enregistrer</button><span class="state">'+(item.image_url?'Photo configurée':'Aucune photo enregistrée')+'</span></div></form></div></article>';}).join('');
document.querySelectorAll('.partner-form').forEach(form=>{const input=form.elements.image,preview=$('.preview',form.closest('.card'));input.addEventListener('change',()=>{const file=input.files?.[0];if(!file)return;if(file.size>8*1024*1024){notice('Cette image dépasse 8 Mo.','error');input.value='';return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){notice('Choisissez un fichier JPG, PNG ou WebP.','error');input.value='';return;}preview.src=URL.createObjectURL(file);preview.hidden=false;});form.addEventListener('submit',save);});}
async function load(){try{const r=await fetch('../api/admin/partner-media.php',{credentials:'same-origin',headers:{'Accept':'application/json'}});const p=await r.json();if(!r.ok)throw new Error(p.error?.message||'Chargement impossible.');render(p.data||[]);notice('Les images et leurs textes sont chargés.');}catch(e){notice(e.message+' Vérifiez que la migration 005 est appliquée à la base de données.','error');}}
async function save(event){event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),state=form.querySelector('.state'),data=new FormData(form);button.disabled=true;state.textContent='Enregistrement…';try{const r=await fetch('../api/admin/partner-media.php',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrfToken,'Accept':'application/json'},body:data});const p=await r.json();if(!r.ok)throw new Error(p.error?.message||'Enregistrement impossible.');if(p.data?.image_url){const preview=$('.preview',form.closest('.card'));preview.src=p.data.image_url+'?v='+Date.now();preview.hidden=false;}state.textContent='Enregistré';notice('Modifications enregistrées. Actualisez la page d’accueil pour vérifier le résultat.','success');}catch(e){state.textContent='Échec';notice(e.message,'error');}finally{button.disabled=false;}}
load();
</script></body></html>